export interface Vector3Like {
  x: number;
  y: number;
  z: number;
}
export interface Size3D {
  width: number;
  height: number;
  depth: number;
}

export type DeviceStatus =
  | "normal"
  | "warning"
  | "critical"
  | "offline"
  | "unknown"
  | "maintenance"
  | "acknowledged"
  | "stale";

export type DeviceType =
  | "server"
  | "switch"
  | "router"
  | "firewall"
  | "database"
  | "storage"
  | "vm"
  | "container"
  | "load_balancer"
  | "access_point"
  | "cloud_service"
  | "unknown";

export type SpaceType =
  | "building"
  | "floor"
  | "site"
  | "zone"
  | "rack"
  | "custom_group"
  | "security_zone"
  | "service"
  | "external"
  | "cloud";

export type EdgeType =
  | "physical"
  | "logical"
  | "service_dependency"
  | "traffic_flow"
  | "security_path"
  | "manual"
  | "inferred";

export type EditorMode = "view" | "edit";

// Host-owned transport health (REST poll / WebSocket / etc). Not derived
// automatically — the host calls `editor.setConnectionStatus(...)` itself.
export type ConnectionStatus = "connected" | "reconnecting" | "disconnected";

export type EditorAction =
  | "view"
  | "layout:update"
  | "space:create"
  | "space:update"
  | "space:delete"
  | "device:map"
  | "device:unmap"
  | "annotation:create"
  | "annotation:update"
  | "annotation:delete"
  | "topology:createLink"
  | "topology:updateLink"
  | "topology:deleteLink"
  | "virtualNode:create"
  | "virtualNode:update"
  | "virtualNode:delete"
  | "background:create"
  | "background:update"
  | "background:delete"
  | "import"
  | "rawDevice:update";

export interface DeviceMetrics {
  cpu?: number;
  memory?: number;
  disk?: number;
  networkIn?: number;
  networkOut?: number;
  temperature?: number;
  [key: string]: number | undefined;
}

export interface RawDevice {
  id: string;
  source: string;
  externalId: string;
  hostname?: string;
  ip?: string;
  mac?: string;
  normalizedType?: string;
  vendor?: string;
  model?: string;
  os?: string;
  status?: DeviceStatus;
  metrics?: DeviceMetrics;
  tenantId?: string;
  customerId?: string;
  siteId?: string;
  firstSeenAt?: string;
  lastSeenAt?: string;
  syncState?: "active" | "missing" | "stale" | "archived";
  externalUrl?: string;
  metadata?: Record<string, unknown>;
}

export interface NetworkInterface {
  id: string;
  rawDeviceId: string;
  name: string;
  alias?: string;
  mac?: string;
  ip?: string;
  status?: "up" | "down" | "unknown";
  speed?: number;
  trafficIn?: number;
  trafficOut?: number;
  errors?: number;
  discards?: number;
}

export interface NetworkLink {
  id: string;
  sourceDeviceId: string;
  targetDeviceId: string;
  sourceInterfaceId?: string;
  targetInterfaceId?: string;
  type: EdgeType;
  status?: "up" | "down" | "unknown";
  bandwidth?: number;
  source: "discovered" | "manual" | "cmdb" | "inferred" | "import";
  confidence?: "high" | "medium" | "low";
  lastUpdatedAt?: string;
  label?: string;
  memo?: string;
  midX?: number;
  midZ?: number;
}

// ─── Toast ──────────────────────────────────────────────────────────────────

export interface Toast {
  id: string;
  message: string;
  type: "info" | "warning" | "critical" | "success";
  timestamp: number;
}

export interface Space {
  id: string;
  name: string;
  kind: "physical" | "logical" | "virtual";
  type: SpaceType;
  parentId?: string;
  source: "manual" | "api" | "cmdb" | "import";
  externalId?: string;
  position?: Vector3Like;
  rotation?: Vector3Like;
  size?: Size3D;
  color?: string;
  archived?: boolean;
  createdAt?: string;
  updatedAt?: string;
}

export interface DeviceMapping {
  id: string;
  rawDeviceId: string;
  primarySpaceId?: string;
  slotIndex?: number;
  mappingStatus:
    | "unmapped"
    | "auto_mapped"
    | "mapped"
    | "needs_review"
    | "ignored"
    | "orphaned";
  displayName?: string;
  visualType?: string;
  position?: Vector3Like;
  rotation?: Vector3Like;
  tags?: string[];
  memo?: string;
  importance?: "low" | "normal" | "high" | "critical";
  operatorState?: OperatorState;
  updatedAt?: string;
  updatedBy?: string;
}

export interface OperatorState {
  acknowledged?: boolean;
  acknowledgedBy?: string;
  acknowledgedAt?: string;
  maintenanceMode?: boolean;
  maintenanceUntil?: string;
  suppressed?: boolean;
  memo?: string;
  assignedTo?: string;
  assignedAt?: string;
}

export type EditorChangeType =
  | "layout.update"
  | "space.create"
  | "space.update"
  | "space.archive"
  | "device.map"
  | "device.unmap"
  | "annotation.update"
  | "topology.link.create"
  | "topology.link.update"
  | "topology.link.delete";

export interface EditorChange {
  id: string;
  type: EditorChangeType;
  targetType: "device" | "space" | "link";
  targetId: string;
  before?: unknown;
  after?: unknown;
  source: "user" | "api" | "import";
  timestamp: string;
}

export interface EditorSnapshot {
  version: string;
  timestamp: string;
  spaces: Space[];
  deviceMappings: DeviceMapping[];
  manualLinks: NetworkLink[];
  backgroundObjects: BackgroundObject[];
}

// ─── Feature Flags ──────────────────────────────────────────────────────────

export interface FeatureFlags {
  view?: boolean;
  search?: boolean;
  filter?: boolean;
  deviceDetail?: boolean;
  topologyView?: boolean;
  topologyEdit?: boolean;
  realtimeUpdate?: boolean;
  savedView?: boolean;
  layoutEdit?: boolean;
  spaceEdit?: boolean;
  annotationEdit?: boolean;
  import?: boolean;
  tour?: boolean;
  backgroundEdit?: boolean;
  // Injects fake random status changes for demos/QA — opt-in only, since a
  // production NOC screen must never show alarms that aren't real.
  chaosSimulator?: boolean;
}

export const DEFAULT_FEATURES: Required<FeatureFlags> = {
  view: true,
  search: true,
  filter: true,
  deviceDetail: true,
  topologyView: true,
  topologyEdit: false,
  realtimeUpdate: true,
  savedView: false,
  layoutEdit: false,
  spaceEdit: false,
  annotationEdit: false,
  import: false,
  tour: true,
  backgroundEdit: true,
  chaosSimulator: false,
};

// ─── Permission ──────────────────────────────────────────────────────────────

export interface PermissionContext {
  action: EditorAction;
  target?: { id?: string; spaceId?: string; siteId?: string };
  userContext?: Record<string, unknown>;
  currentMode?: EditorMode;
}

export type PermissionResolver = (ctx: PermissionContext) => boolean;

export interface EditorEventPayload<T = unknown> {
  type: string;
  target?: { id?: string; type?: string };
  source: "user" | "api" | "plugin" | "system";
  timestamp: number;
  before?: T;
  after?: T;
}

export interface EditorData {
  devices?: RawDevice[];
  spaces?: Space[];
  deviceMappings?: DeviceMapping[];
  links?: NetworkLink[];
  interfaces?: NetworkInterface[];
  unmappedDevices?: RawDevice[];
  virtualNodes?: VirtualNode[];
  backgroundObjects?: BackgroundObject[];
}

export interface EditorOptions {
  container?: HTMLElement;
  data?: EditorData;
  features?: FeatureFlags;
  permissionResolver?: PermissionResolver;
  mode?: EditorMode;
  mockData?: boolean;
  // Root space (building/site) or floor to land on instead of the 2D campus overview.
  initialFloorId?: string;
  onReady?: () => void;
  onChange?: (event: EditorEventPayload) => void;
  onSave?: (snapshot: EditorSnapshot) => void | Promise<void>;
  onError?: (error: Error, context?: Record<string, unknown>) => void;
  onPermissionDenied?: (ctx: PermissionContext) => void;
  onPerformanceWarning?: (metric: Record<string, unknown>) => void;
  onOpenExternal?: (url: string, ctx?: Record<string, unknown>) => void;
  shadowDom?: boolean;
  stylesheetUrl?: string;
  styleNonce?: string;
}

// ─── Selection ───────────────────────────────────────────────────────────────

export interface SelectionTarget {
  type: "device" | "space" | "link" | "background";
  id: string;
}

// ─── Filter ──────────────────────────────────────────────────────────────────

export interface FilterState {
  search: string;
  status: DeviceStatus[];
  type: DeviceType[];
  spaceId: string | null;
  tags: string[];
  showUnmapped: boolean;
}

export const DEFAULT_FILTER: FilterState = {
  search: "",
  status: [],
  type: [],
  spaceId: null,
  tags: [],
  showUnmapped: true,
};

// ─── Virtual Node ────────────────────────────────────────────────────────────

export interface VirtualNode {
  id: string;
  label: string;
  description?: string;
  type: "internet" | "cloud" | "external" | "custom";
  position?: Vector3Like;
  spaceId?: string;
  tags?: string[];
  createdAt?: string;
}

// ─── Background Objects ─────────────────────────────────────────────────────
// User-placed reference geometry (floor-plan images, building/room models) —
// a per-floor tracing guide for laying out devices/spaces. Only movable while
// `ui.backgroundEditActive` is on; otherwise translucent and click-through.

export interface BackgroundObject {
  id: string;
  name: string;
  kind: "image" | "model";
  spaceId: string; // which floor/space this belongs to
  assetId: string; // key into backgroundStorage's IndexedDB store
  position: Vector3Like;
  rotationY?: number; // degrees — flat-on-ground objects only need yaw
  scale?: number; // uniform scale factor (models)
  width?: number; // image only — real-world plane width
  depth?: number; // image only — real-world plane depth
  opacity?: number; // "dashboard view" opacity, default 0.3
  createdAt?: string;
}

// ─── Custom Device Types ─────────────────────────────────────────────────────

export type CustomShape = "box" | "cylinder" | "sphere" | "octahedron";

export interface CustomDeviceType {
  id: string; // unique key, used as the type string in rendering
  label: string; // display name e.g. "Core Router"
  abbr: string; // ≤4 chars for badge e.g. "CR"
  color: string; // hex color
  shape: CustomShape;
  w: number; // width (or diameter for non-box)
  h: number; // height
  d: number; // depth (box only)
  hasModel?: boolean; // true when a GLTF/GLB model is stored in IndexedDB for this type
}

// ─── Saved View ──────────────────────────────────────────────────────────────

export interface SavedView {
  id: string;
  name: string;
  cameraPos: Vector3Like;
  cameraTarget: Vector3Like;
  filters?: Partial<FilterState>;
  createdAt: string;
  /** Small data-URL snapshot of the canvas at save time, shown in the saved-view list. */
  thumbnail?: string;
}

export interface LinkDraftState {
  active: boolean;
  sourceDeviceId: string | null;
}

// ─── Auto Layout ─────────────────────────────────────────────────────────────

export interface AutoLayoutOptions {
  /** Restrict the run to these device ids; defaults to every known device. */
  deviceIds?: string[];
  /** Re-lay-out devices that already have a manual position too, instead of
   *  leaving them fixed in place. Default false. */
  includeMapped?: boolean;
  /** Simulation iterations — higher settles further but takes longer. Default 200. */
  iterations?: number;
  /** Called with a 0..1 completion fraction as the layout runs. */
  onProgress?: (fraction: number) => void;
}

export interface AutoLayoutProgress {
  iteration: number;
  iterations: number;
}
